import React, { useState, useEffect } from "react";
import DailyTracker from "../components/DailyTracker";
import ProgressBar from "../components/ProgressBar";
import StreakCard from "../components/StreakCard";
import MonthlyChart from "../components/MonthlyChart";
import GoalMeter from "../components/GoalMeter";
import BadHabitWarning from "../components/BadHabitWarning";
import { calculateStreak } from "../utils/streakCalculator";
import SpiritualRoutineCard from "../components/SpiritualRoutineCard";
import SatsangCard from "../components/SatsangCard";
import RoutineTimeline from "../components/RoutineTimeline";
import MotivationCard from "../components/MotivationCard";
import DayStatusDots from "../components/DayStatusDots";
import JapMethodCard from "../components/JapMethodCard";
import WakeUpTracker from "../components/WakeUpTracker";
import JapReminder from "../components/JapReminder";
import MalaCounter from "../components/MalaCounter";
import KrupaPoints from "../components/KrupaPoints";
import JapTimer from "../components/JapTimer";
import EmergencyJap from "../components/EmergencyJap";
import MindReset from "../components/MindReset";

export default function Dashboard() {

  const [score, setScore] = useState(0);
  const [noFap, setNoFap] = useState(true);
  const [japDone, setJapDone] = useState(false);

  // ✅ Move useEffect INSIDE component
  useEffect(() => {
    const hour = new Date().getHours();

    if (hour > 8) {
      alert("⚠️ Mobile check before Jap = streak risk");
    }
  }, []);

  // Dummy monthly data
  const monthlyData = [
    { date: "1", score: 3 },
    { date: "2", score: 4 },
    { date: "3", score: 5 },
    { date: "4", score: 2 },
    { date: "5", score: 6 }
  ];

  const streak = calculateStreak(monthlyData);
  const completedDays = monthlyData.filter(d => d.score >= 4).length;

  const [selfCheck, setSelfCheck] = useState({
    jap: false,
    satsang: false,
    mobile: false
  });

  const [satsang, setSatsang] = useState({
    mandir: false,
    group: false,
    bhajan: false
  });

  return (
    <>
      <div style={{
        maxWidth: "900px",
        margin: "auto",
        padding: "10px"
      }}>
        <h2>Dashboard</h2>

        <BadHabitWarning score={score} noFap={noFap} />

        <div style={{
          display: "grid",
          gridTemplateColumns: "1fr 1fr",
          gap: "15px"
        }}>
          <StreakCard streak={streak} />
          <GoalMeter totalDays={30} completedDays={completedDays} />
        </div>

        <ProgressBar score={score} total={6} />

        <DailyTracker
          onScoreChange={(s, nf) => {
            setScore(s);
            setNoFap(nf);
          }}
        />

        <MonthlyChart data={monthlyData} />
      </div>

      <div style={{
        maxWidth: "500px",
        margin: "auto",
        padding: "10px"
      }}>
        <MotivationCard />

        <SpiritualRoutineCard
          japDone={japDone}
          setJapDone={setJapDone}
          selfCheck={selfCheck}
          setSelfCheck={setSelfCheck}
        />

        <SatsangCard satsang={satsang} setSatsang={setSatsang} />

        <RoutineTimeline />

        <DayStatusDots />
        <JapMethodCard />

        <JapReminder />
        <WakeUpTracker />
        <MalaCounter />
        <KrupaPoints />


        <JapTimer onComplete={() => setScore(prev => prev + 5)} />

<EmergencyJap onMini={() => setScore(prev => prev + 2)} />

<MindReset />

      </div>
    </>
  );
}
